function smarttoolz_video_show_admin_bar( $show ) { if ( is_admin() ) return $show; $user=wp_get_current_user(); if(!$user||!$user->exists())return false; return in_array('administrator',(array)$user->roles,true); }
add_filter('show_admin_bar','smarttoolz_video_show_admin_bar',999);
function smarttoolz_video_hide_admin_bar_css(){if(is_admin())return;$user=wp_get_current_user();if(!$user||!$user->exists()||!in_array('administrator',(array)$user->roles,true))echo '<style id="smarttoolz-hide-wp-admin-bar">#wpadminbar{display:none!important}html{margin-top:0!important}</style>';}
